import{_ as e,o as r,c as f,a3 as t}from"./chunks/framework.CJlOecQn.js";const d=JSON.parse('{"title":"الوصول والتأشيرات","description":"الطرق الرئيسية لدخول دولة قطر، وما تحتاجه في المنفذ، وكيفية الاستعلام عن التأشيرة عبر موقع وزارة الداخلية.","frontmatter":{"title":"الوصول والتأشيرات","description":"الطرق الرئيسية لدخول دولة قطر، وما تحتاجه في المنفذ، وكيفية الاستعلام عن التأشيرة عبر موقع وزارة الداخلية.","lastChecked":"2026-10","sourceCount":10},"headers":[],"relativePath":"ar/guide/arriving-and-visas.md","filePath":"ar/guide/arriving-and-visas.md"}'),o={name:"ar/guide/arriving-and-visas.md"};function s(n,a,i,l,c,p){return r(),f("div",null,[...a[0]||(a[0]=[t('<h1 id="الوصول-والتأشيرات" tabindex="-1">الوصول والتأشيرات <a class="header-anchor" href="#الوصول-والتأشيرات" aria-label="Permalink to &quot;الوصول والتأشيرات&quot;">​</a></h1><p>تعتمد طريقة دخولك إلى دولة قطر على جنسيتك وسبب قدومك. فالزائر قد يحصل على تأشيرة فورية عند الوصول أو يتقدم إلكترونيًا عبر منصة هيّا، أما من ينتقل للإقامة فيدخل بسمة إقامة ثم يكمل إجراءات الإقامة بعد وصوله.<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup></p><p>تنبّه وزارة الداخلية إلى أن قواعد تأشيرات الزوار قد تتغير دون إشعار، لذا راجع القواعد الخاصة بجنسيتك قبل موعد سفرك بوقت قصير.<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1]</a></sup></p><h2 id="طرق-الدخول" tabindex="-1">طرق الدخول <a class="header-anchor" href="#طرق-الدخول" aria-label="Permalink to &quot;طرق الدخول&quot;">​</a></h2><h3 id="التأشيرة-عند-الوصول-أو-الإعفاء-من-التأشيرة-المسبقة" tabindex="-1">التأشيرة عند الوصول أو الإعفاء من التأشيرة المسبقة <a class="header-anchor" href="#التأشيرة-عند-الوصول-أو-الإعفاء-من-التأشيرة-المسبقة" aria-label="Permalink to &quot;التأشيرة عند الوصول أو الإعفاء من التأشيرة المسبقة&quot;">​</a></h3><ul><li>تذكر وزارة الداخلية أن رعايا أكثر من 95 دولة يحق لهم دخول قطر بتأشيرة فورية عند الوصول إلى منافذ الدولة، وأن مواطني عدد من الدول معفيون من تأشيرة الدخول المسبقة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:2">[1]</a></sup></li><li>تختلف مدة البقاء بحسب الجنسية.<sup class="footnote-ref"><a href="#fn1" id="fnref1:3">[1]</a></sup> وتعرض صفحة التأشيرات عند الوصول فئتين سياحيتين لمدة 90 يومًا و30 يومًا، إلى جانب فئات أخرى مثل تأشيرة مقيمي دول مجلس التعاون وتأشيرة الأعمال بشروطها الخاصة.<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li><li>لا يحتاج مواطنو دول مجلس التعاون الخليجي إلى تأشيرة، وتوضح منصة هيّا أن جواز السفر أو البطاقة الخليجية يكفيان.<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup></li></ul><h3 id="تأشيرات-منصة-هيّا" tabindex="-1">تأشيرات منصة هيّا <a class="header-anchor" href="#تأشيرات-منصة-هيّا" aria-label="Permalink to &quot;تأشيرات منصة هيّا&quot;">​</a></h3><ul><li>هيّا هي المنصة الإلكترونية للتأشيرات السياحية، وتدرج وزارة الداخلية عليها أربعة أنواع من سمات الدخول: سمة الدخول السياحية، وسمة دخول مقيمي دول مجلس التعاون الخليجي، وسمة دخول مرافقي مواطني دول مجلس التعاون الخليجي، وسمة الدخول عن طريق إخطار السفر الإلكتروني ETA.<sup class="footnote-ref"><a href="#fn1" id="fnref1:4">[1]</a></sup></li><li>تقدّم طلبك عبر موقع hayya.qa أو تطبيق هيّا على الهاتف.<sup class="footnote-ref"><a href="#fn1" id="fnref1:5">[1]</a></sup><sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4]</a></sup></li></ul><h3 id="التأشيرات-المسبقة" tabindex="-1">التأشيرات المسبقة <a class="header-anchor" href="#التأشيرات-المسبقة" aria-label="Permalink to &quot;التأشيرات المسبقة&quot;">​</a></h3><ul><li>هي تأشيرات تحصل عليها قبل السفر وتبرزها في منفذ الوصول، وتشمل قائمة وزارة الداخلية تأشيرات الأعمال والتأشيرات العائلية (الزيارة الشخصية)، ولهذه الأخيرة صفحة خاصة: <a href="./family-visas">التأشيرات العائلية</a>.<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup></li></ul><h3 id="القدوم-للإقامة-أو-العمل" tabindex="-1">القدوم للإقامة أو العمل <a class="header-anchor" href="#القدوم-للإقامة-أو-العمل" aria-label="Permalink to &quot;القدوم للإقامة أو العمل&quot;">​</a></h3><ul><li>تخصص وزارة الداخلية تأشيرة العمل على كفالة الشركات للعاملين المستقدمين للعمل في الوزارات والجهات الحكومية وشبه الحكومية والشركات الخاصة.<sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup></li><li>تذكر الوزارة هذه الشروط: شهادات دراسية مصدقة، وعقد عمل بينك وبين صاحب العمل، وشهادة حسن سيرة وسلوك من بلدك مصدقة من سفارة قطر هناك، واجتياز الفحص الطبي خارج قطر.<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6]</a></sup></li><li>إذا دخلت بسمة إقامة، فعليك إجراء الفحص الطبي خلال ثلاثين يومًا من دخولك البلاد، ثم تؤخذ البصمة بعد الفحص، وبعدها تُستكمل إجراءات الإقامة. وتجد التفاصيل في صفحة <a href="./residence-permit-and-qid">رخصة الإقامة والبطاقة الشخصية</a>.<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2]</a></sup></li></ul><h2 id="ما-تجهزه-قبل-الوصول-إلى-المنفذ" tabindex="-1">ما تجهزه قبل الوصول إلى المنفذ <a class="header-anchor" href="#ما-تجهزه-قبل-الوصول-إلى-المنفذ" aria-label="Permalink to &quot;ما تجهزه قبل الوصول إلى المنفذ&quot;">​</a></h2><ul><li>جواز سفر ساري المفعول. وتختلف صفحتان من صفحات وزارة الداخلية في المدة المطلوبة: فصفحة سمات الدخول للزيارات تذكر ثلاثة أشهر على الأقل، وصفحة شروط التأشيرة تذكر مدة لا تقل عن 6 أشهر.<sup class="footnote-ref"><a href="#fn1" id="fnref1:6">[1]</a></sup><sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup> ووجود صلاحية 6 أشهر أو أكثر يفي بالشرطين معًا.<sup class="footnote-ref"><a href="#fn7" id="fnref7:1">[7]</a></sup></li><li>تذكرة مؤكدة لمتابعة الرحلة أو تذكرة ذهاب وعودة مؤكدة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:7">[1]</a></sup></li><li>وثيقة تأمين صحي سارية من شركة تأمين مسجلة لدى وزارة الصحة العامة.<sup class="footnote-ref"><a href="#fn1" id="fnref1:8">[1]</a></sup></li><li>لبعض الجنسيات: حجز فندقي أو مبلغ نقدي أو بطاقة ائتمان.<sup class="footnote-ref"><a href="#fn7" id="fnref7:2">[7]</a></sup></li><li>إذا كنت قادمًا بسيارتك: تأمين المركبة. ويُنجز القادمون عبر منفذ أبو سمرة الحدودي وثائق التأمين المطلوبة إلكترونيًا، ويمكنهم التسجيل المسبق عبر منصة هيّا.<sup class="footnote-ref"><a href="#fn1" id="fnref1:9">[1]</a></sup></li></ul><h2 id="كيفية-الاستعلام-عن-التأشيرة" tabindex="-1">كيفية الاستعلام عن التأشيرة <a class="header-anchor" href="#كيفية-الاستعلام-عن-التأشيرة" aria-label="Permalink to &quot;كيفية الاستعلام عن التأشيرة&quot;">​</a></h2><ul><li>تتيح صفحة خدمات التأشيرات في وزارة الداخلية متابعة الموافقة على تأشيرة العمل أو الزيارة برقم الطلب، أو الاستعلام عنها برقم التأشيرة، وطباعة بيانات التأشيرة الصادرة.<sup class="footnote-ref"><a href="#fn8" id="fnref8">[8]</a></sup></li><li>تتضمن الصفحة نفسها خيار متابعة حالة الطلب لدى مركز تأشيرات قطر.<sup class="footnote-ref"><a href="#fn8" id="fnref8:1">[8]</a></sup></li><li>لتأشيرة هيّا الإلكترونية، استخدم خدمة تتبع التأشيرة برقم مرجع الدخول، أو برقم جواز السفر والجنسية.<sup class="footnote-ref"><a href="#fn9" id="fnref9">[9]</a></sup></li></ul><h2 id="تمديد-البقاء-وتجاوز-المدة" tabindex="-1">تمديد البقاء وتجاوز المدة <a class="header-anchor" href="#تمديد-البقاء-وتجاوز-المدة" aria-label="Permalink to &quot;تمديد البقاء وتجاوز المدة&quot;">​</a></h2><ul><li>تأكد عند دخولك من المدة التي تسمح بها تأشيرة الزيارة. وتذكر وزارة الداخلية أن الزيارة العائلية تمنح شهرًا واحدًا.<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2]</a></sup></li><li>إذا أردت البقاء أكثر في الزيارة العائلية، فأكمل الفحص الطبي قبل انتهاء المدة المسموح بها وقدّم طلب التمديد.<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2]</a></sup></li><li>إذا انتهت التأشيرة دون تمديد، تفرض الوزارة غرامة عن كل يوم تأخير بحد أقصى، والمبالغ مذكورة في صفحة الإرشادات.<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2]</a></sup></li><li>تتضمن صفحة خدمات التأشيرات أيضًا خيار تمديد التأشيرة ودفع الغرامة.<sup class="footnote-ref"><a href="#fn8" id="fnref8:2">[8]</a></sup></li><li>يمكنك الاستعلام عن مخالفات تجاوز المدة عبر خدمة الاستعلام عن مخالفات تجاوز مدة الإقامة.<sup class="footnote-ref"><a href="#fn10" id="fnref10">[10]</a></sup></li></ul><p>انظر أيضًا: <a href="./residence-permit-and-qid">رخصة الإقامة والبطاقة الشخصية</a>، <a href="./family-visas">التأشيرات العائلية</a>، <a href="./metrash">مطراش</a>.</p><h2 id="المصادر" tabindex="-1">المصادر <a class="header-anchor" href="#المصادر" aria-label="Permalink to &quot;المصادر&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/qatarvisasar/index.html" target="_blank" rel="noreferrer">سمات (تأشيرات) الدخول للزيارات</a>. آخر تحقق: 2026-10. <a href="#fnref1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:5" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:8" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref1:9" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn2" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/47" target="_blank" rel="noreferrer">نصائح وإرشادات (Tips &amp; Guidelines)</a>. آخر تحقق: 2026-10. <a href="#fnref2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:3" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref2:4" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn3" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/c27493" target="_blank" rel="noreferrer">التأشيرات عند الوصول (On-arrival visas)</a>. آخر تحقق: 2026-10. <a href="#fnref3" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn4" class="footnote-item"><p>هيّا، <a href="https://hayya.qa/en" target="_blank" rel="noreferrer">بوابة هيّا</a>. آخر تحقق: 2026-10. <a href="#fnref4" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref4:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn5" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/c29604" target="_blank" rel="noreferrer">التأشيرات المسبقة (Visas in advance)</a>. آخر تحقق: 2026-10. <a href="#fnref5" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn6" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/otherservices/?1dmy&amp;page=pg.moi.internet.departments.services.detail&amp;uri=wcm%3Apath%3Awcmlib-internet-en%2Fsa-departmentcommittee%2Fgeneraladministrationofnationalitybordersandexpatriateaffairs%2Fservices%2Fwork%2Bentry%2Fqr%25240" target="_blank" rel="noreferrer">تأشيرة العمل على كفالة الشركات (Work Visa on Company Sponsorship)</a>. آخر تحقق: 2026-10. <a href="#fnref6" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref6:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn7" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/wcm/connect/wcmlib-internet-en/sa-departmentcommittee/generaladministrationofnationalitybordersandexpatriateaffairs/visas/768" target="_blank" rel="noreferrer">شروط التأشيرة (Visa Conditions)</a>. آخر تحقق: 2026-10. <a href="#fnref7" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref7:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref7:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn8" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/visaservices" target="_blank" rel="noreferrer">خدمات التأشيرات (Visa Services)</a>. آخر تحقق: 2026-10. <a href="#fnref8" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref8:1" class="footnote-backref" aria-label="العودة إلى النص">↑</a> <a href="#fnref8:2" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn9" class="footnote-item"><p>هيّا، <a href="https://hayya.qa/en/visa-inquiry" target="_blank" rel="noreferrer">تتبع تأشيرتك الإلكترونية (Track your E-Visa)</a>. آخر تحقق: 2026-10. <a href="#fnref9" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li><li id="fn10" class="footnote-item"><p>وزارة الداخلية، <a href="https://portal.moi.gov.qa/wps/portal/MOIInternet/services/inquiries/overstay" target="_blank" rel="noreferrer">البحث والمتابعة (Search and Follow up)</a>. آخر تحقق: 2026-10. <a href="#fnref10" class="footnote-backref" aria-label="العودة إلى النص">↑</a></p></li></ol></section>',22)])])}const u=e(o,[["render",s]]);export{d as __pageData,u as default};
